from abc import ABC, abstractmethod
from pathlib import Path
from fractions import Fraction
from mung import NotationGraph

ASSETS_DIR = Path(__file__).parent


class AssetExample(ABC):
    @property
    @abstractmethod
    def dir(self) -> Path:
        pass

    def get_graph_file(self) -> Path:
        return list(self.dir.glob("*.xml"))[0]
    
    def get_image_file(self) -> Path:
        exts = {".png", ".jpg", ".jpeg", ".bmp", ".gif", ".tiff", ".webp"}
        return [p for p in self.dir.glob("*") if p.suffix.lower() in exts][0]

    def get_graph(self) -> NotationGraph:
        return NotationGraph.from_file(self.get_graph_file())

    @property
    @abstractmethod
    def expected_onsets(self) -> dict[int, Fraction]:
        pass

    @property
    @abstractmethod
    def expected_durations(self) -> dict[int, Fraction]:
        pass
    
    @property
    @abstractmethod
    def expected_durations_without_modifiers(self) -> dict[int, Fraction]:
        pass


